// @ts-check
import { generateGUID } from '../../utils/guid/generateGuid.js'

/** @type {Map<string, any>} */
const _cache = new Map()

/** @type {ReferencesCache | null} */
let _instance = null

class ReferencesCache {
    constructor() {
        if (_instance !== null) {
            throw new Error('ReferencesCache is a singleton — use ReferencesCache.getInstance()')
        }
    }

    /**
     * @returns {ReferencesCache}
     */
    static getInstance() {
        if (_instance === null) {
            _instance = new ReferencesCache()
        }
        return _instance
    }

    /**
     * @param {any} reference
     * @returns {string}
     */
    cacheReference(reference) {
        const id = generateGUID()
        _cache.set(id, reference)
        return id
    }

    /**
     * @param {string} id
     * @returns {any}
     */
    resolveReference(id) {
        return _cache.get(id)
    }

    /**
     * @param {string} reference_guid
     * @returns {boolean}
     */
    deleteReference(reference_guid) {
        if (reference_guid == null || typeof reference_guid !== 'string') {
            return false
        }
        return _cache.delete(reference_guid)
    }
}

export { ReferencesCache }
