// @ts-check
import { Http2Client } from '../http2Client/Http2Client.js'
import { Http2ConnectionData } from '../../utils/connectionData/Http2ConnectionData.js'

export class TransmitterHttp2 {
    /**
     * @returns {void}
     */
    static initialize() {}

    /**
     * @returns {void}
     */
    static setConfigSource() {}

    /**
     * @returns {void}
     */
    static activate() {}

    /**
     * @async
     * @param {Uint8Array} messageByteArray
     * @param {Http2ConnectionData} connectionData
     * @returns {Promise<Uint8Array>} responseByteArray
     */
    static sendCommand(messageByteArray, connectionData) {
        const options = {
            isDisconnectedAfterMessage: false,
        }
        return new Http2Client(connectionData, options).send(messageByteArray)
    }
}
