// @ts-check
import { AbstractHandler } from './AbstractHandler.js'
import { Command } from '../../utils/Command.js'
import { GetTypeHandler } from './GetTypeHandler.js'
import { ArrayHandler } from './ArrayHandler.js'
import { CommandType } from '../../utils/CommandType.js'
import { RuntimeName } from '../../utils/RuntimeName.js'

export class ContextMetadataHandler extends AbstractHandler {
    constructor() {
        super()
        /**
         * Minimum required parameters count for the command.
         * @type {number}
         */
        this.requiredParametersCount = 1
        this.getTypeHandler = new GetTypeHandler()
        this.arrayHandler = new ArrayHandler()
    }

    /**
     * @param {Command} command - The command to process.
     * @returns {number}
     */
    process(command) {
        this.validate(command, this.requiredParametersCount, this.constructor.name)

        const getTypeCommand = new Command(RuntimeName.Nodejs, CommandType.GetType, ['RequestContext'])
        const contextType = this.getTypeHandler.process(getTypeCommand)

        const currentContext = contextType.current

        const arrayCommand = command.payload[0]

        if (arrayCommand instanceof Command && arrayCommand.commandType === CommandType.Array) {
            const values = this.arrayHandler.process(arrayCommand)
            if (values.length % 2 !== 0) {
                throw new Error('Context metadata payload must contain key/value pairs.')
            }
            /** @type {Record<string, string>} */
            const headers = {}
            for (let i = 0; i < values.length; i += 2) {
                const rawKey = values[i]
                if (rawKey == null || String(rawKey).trim() === '') {
                    throw new Error('Context metadata key cannot be null or empty.')
                }
                headers[String(rawKey)] = values[i + 1] == null ? '' : String(values[i + 1])
            }

            currentContext.setHeaders(headers)
        } else {
            throw new Error('Context metadata payload must be an array command.')
        }

        return 0
    }
}
