//@ts-check
import { getRequire, isNodejsRuntime } from '../../utils/Runtime.js'

const requireDynamic = getRequire(import.meta.url)

/** @type {typeof import('node:http2') | null} */
let http2 = null

/** @type {Record<string, Http2Client>} */
export const clients = {}

const MAX_ATTEMPTS = 2
const DEFAULT_CONNECT_TIMEOUT_SECONDS = 120
const DEFAULT_CONNECT_TIMEOUT_MS = DEFAULT_CONNECT_TIMEOUT_SECONDS * 1000
const DEFAULT_RESPONSE_TIMEOUT_SECONDS = 180
const DEFAULT_RESPONSE_TIMEOUT_MS = DEFAULT_RESPONSE_TIMEOUT_SECONDS * 1000

/**
 * @typedef {import('../../utils/connectionData/Http2ConnectionData.js').Http2ConnectionData} Http2ConnectionData
 */

class Http2Client {
    /**
     * @param {Http2ConnectionData} connectionData
     * @param {{ isDisconnectedAfterMessage: boolean }} [options]
     */
    constructor(connectionData, options) {
        this.connectionData = connectionData
        this.url = connectionData.hostname
        this.isDisconnectedAfterMessage = options?.isDisconnectedAfterMessage ?? false
        this.options = options
        this.responseTimeoutInSeconds =
            connectionData.responseTimeoutInSeconds ?? DEFAULT_RESPONSE_TIMEOUT_SECONDS
        this.session = null
        this.disposed = false

        const parsedUrl = new URL(this.url)
        if (parsedUrl.protocol !== 'http:' && parsedUrl.protocol !== 'https:') {
            throw new Error(
                `Http2Client requires 'http' (h2c) or 'https' (h2 over TLS) scheme. Provided URL: ${this.url}`
            )
        }
        this.requestPath = `${parsedUrl.pathname || '/'}${parsedUrl.search || ''}`
        this.requestScheme = parsedUrl.protocol.replace(':', '')
        this.requestAuthority = parsedUrl.host
        this.requestHeaders = this._buildRequestHeadersFromConnectionData()
    }

    get cacheKey() {
        return this.connectionData.toCanonicalKey()
    }

    /**
     * @param {Uint8Array} messageArray
     * @returns {Promise<Uint8Array>}
     */
    send(messageArray) {
        if (messageArray == null) {
            return Promise.reject(new Error('messageArray must not be null or undefined'))
        }
        const client = Http2Client.createOrGetClient(this.connectionData, this.options, null)
        // Each call opens its own HTTP/2 stream on the shared session.
        return client._sendWithRetry(messageArray)
    }

    disconnect() {
        if (this.session) {
            try {
                this.session.close()
            } catch {
                try {
                    this.session.destroy()
                } catch {
                    // ignore destroy errors during forced cleanup
                }
            }
        }
        this.session = null
        this.disposed = true
        delete clients[this.cacheKey]
    }

    /**
     * @param {Http2ConnectionData} connectionData
     * @param {{ isDisconnectedAfterMessage: boolean }} [options]
     * @param {Http2Client | null} [expectedCurrent]
     * @returns {Http2Client}
     */
    static createOrGetClient(connectionData, options, expectedCurrent) {
        const key = connectionData.toCanonicalKey()

        if (!expectedCurrent) {
            if (clients[key]) {
                return clients[key]
            }
            const created = new Http2Client(connectionData, options)
            clients[key] = created
            return created
        }

        const existing = clients[key]
        if (existing && existing !== expectedCurrent) {
            return existing
        }
        if (existing === expectedCurrent) {
            existing._closeSession()
            delete clients[key]
        }

        const recreated = new Http2Client(connectionData, options)
        clients[key] = recreated
        return recreated
    }

    /**
     * @param {Http2ConnectionData} connectionData
     */
    static closeClient(connectionData) {
        const key = connectionData.toCanonicalKey()
        const client = clients[key]
        if (client) {
            client.disconnect()
        }
    }

    /**
     * @private
     * @param {Uint8Array} messageArray
     * @returns {Promise<Uint8Array>}
     */
    async _sendWithRetry(messageArray) {
        let client = clients[this.cacheKey] || this
        let lastError = null

        for (let attempt = 0; attempt < MAX_ATTEMPTS; attempt++) {
            try {
                return await client._sendOnce(messageArray)
            } catch (error) {
                lastError = error
                const connectionFailed = isConnectionLevelHttp2Error(error) || !isSessionUsable(client)
                if (!isTransientHttp2Error(error) && !connectionFailed) {
                    throw error
                }
                if (attempt === MAX_ATTEMPTS - 1) {
                    break
                }
                if (connectionFailed) {
                    client = Http2Client.createOrGetClient(this.connectionData, this.options, client)
                }
            }
        }

        if (isConnectionLevelHttp2Error(lastError) || !isSessionUsable(client)) {
            // Evict desynced/broken connection after final failure (bug 32346).
            this._evictCachedClient(client)
        }
        throw new Error(
            `HTTP/2 send to ${this.url} failed after ${MAX_ATTEMPTS} attempts. Last error: ${getErrorMessage(lastError)}`
        )
    }

    /**
     * @private
     * @param {Http2Client} client
     */
    _evictCachedClient(client) {
        const cached = clients[this.cacheKey]
        if (cached && cached === client) {
            cached._closeSession()
            delete clients[this.cacheKey]
            return
        }
        if (!cached && client) {
            client._closeSession()
        }
    }

    /**
     * @private
     * @param {Uint8Array} messageArray
     * @returns {Promise<Uint8Array>}
     */
    _sendOnce(messageArray) {
        if (this.disposed) {
            return Promise.reject(createTransientError(`HTTP/2 client is disposed for ${this.url}.`))
        }

        return new Promise((resolve, reject) => {
            const http2Module = getHttp2()
            const session = this._connect()
            const body = toBuffer(messageArray)
            const headers = this._buildRequestHeaders(body)
            /** @type {Buffer[]} */
            const chunks = []
            let completed = false
            /** @type {number | null} */
            let statusCode = null
            let reason = ''

            const cleanup = () => {
                stream.removeAllListeners()
            }

            const fail = (/** @type {Error} */ error) => {
                if (completed) return
                completed = true
                cleanup()
                reject(error)
            }

            const stream = session.request(headers)
            if (this.responseTimeoutInSeconds >= 0) {
                const responseTimeoutMs =
                    this.responseTimeoutInSeconds === DEFAULT_RESPONSE_TIMEOUT_SECONDS
                        ? DEFAULT_RESPONSE_TIMEOUT_MS
                        : this.responseTimeoutInSeconds * 1000
                stream.setTimeout(responseTimeoutMs, () => {
                    stream.close(http2Module.constants.NGHTTP2_CANCEL)
                    fail(
                        createTransientError(
                            `HTTP/2 request to ${this.url} timed out after ${this.responseTimeoutInSeconds} seconds.`
                        )
                    )
                })
            }

            stream.on('response', (responseHeaders) => {
                const rawStatus = responseHeaders[http2Module.constants.HTTP2_HEADER_STATUS]
                statusCode = Number(rawStatus)
                reason = String(responseHeaders['x-http2-reason'] || '')
            })
            stream.on('data', (chunk) => chunks.push(Buffer.from(chunk)))
            stream.on('end', () => {
                if (completed) return
                completed = true
                cleanup()

                if (statusCode === null) {
                    reject(new Error(`HTTP/2 request to ${this.url} completed without a response status.`))
                    return
                }
                if (statusCode < 200 || statusCode >= 300) {
                    reject(
                        new Error(
                            `HTTP/2 request to ${this.url} failed with status ${statusCode} ${reason}. `
                        )
                    )
                    return
                }

                if (this.isDisconnectedAfterMessage) {
                    this.disconnect()
                }
                resolve(Buffer.concat(chunks))
            })
            stream.on('error', fail)
            stream.on('aborted', () =>
                fail(createTransientError(`HTTP/2 stream to ${this.url} was aborted.`))
            )
            stream.on('close', () => {
                if (!completed) {
                    fail(
                        createTransientError(
                            `HTTP/2 stream to ${this.url} was closed before the response completed.`
                        )
                    )
                }
            })
            stream.end(body)
        })
    }

    /**
     * @private
     * @returns {import('node:http2').ClientHttp2Session}
     */
    _connect() {
        if (this.session && !this.session.closed && !this.session.destroyed) {
            return this.session
        }

        const session = getHttp2().connect(this.url)
        let connected = false
        const connectTimeout = setTimeout(() => {
            if (!connected && !session.closed && !session.destroyed) {
                session.destroy(
                    createTransientError(
                        `HTTP/2 connection to ${this.url} timed out after ${DEFAULT_CONNECT_TIMEOUT_SECONDS} seconds.`,
                        true
                    )
                )
            }
        }, DEFAULT_CONNECT_TIMEOUT_MS)

        session.on('connect', () => {
            connected = true
            clearTimeout(connectTimeout)
        })
        session.on('error', () => {})
        session.on('goaway', () => {
            session.destroy(createTransientError(`HTTP/2 session to ${this.url} received GOAWAY.`, true))
        })
        session.on('close', () => {
            clearTimeout(connectTimeout)
            if (this.session === session) {
                this.session = null
                this.disposed = true
            }
        })
        this.session = session
        this.disposed = false
        return session
    }

    /**
     * @private
     */
    _closeSession() {
        if (this.session) {
            try {
                this.session.close()
            } catch {
                try {
                    this.session.destroy()
                } catch {
                    // ignore destroy errors during forced cleanup
                }
            }
        }
        this.session = null
        this.disposed = true
    }

    /**
     * @private
     * @param {Buffer} body
     * @returns {Record<string, string | string[] | number>}
     */
    _buildRequestHeaders(body) {
        const http2Module = getHttp2()
        const requestHeaders = {
            [http2Module.constants.HTTP2_HEADER_METHOD]: http2Module.constants.HTTP2_METHOD_POST,
            [http2Module.constants.HTTP2_HEADER_PATH]: this.requestPath,
            [http2Module.constants.HTTP2_HEADER_SCHEME]: this.requestScheme,
            [http2Module.constants.HTTP2_HEADER_AUTHORITY]: this.requestAuthority,
            [http2Module.constants.HTTP2_HEADER_CONTENT_TYPE]: 'application/octet-stream',
            [http2Module.constants.HTTP2_HEADER_CONTENT_LENGTH]: body.length,
            ...this.requestHeaders,
        }

        return requestHeaders
    }

    /**
     * @private
     * @returns {Record<string, string | string[]>}
     */
    _buildRequestHeadersFromConnectionData() {
        const requestHeaders = /** @type {Record<string, string | string[]>} */ ({})
        for (const [key, value] of Object.entries(this.connectionData.getHeaders())) {
            if (!key || value == null || key.startsWith(':')) {
                continue
            }
            requestHeaders[key.toLowerCase()] = value
        }
        return requestHeaders
    }
}

/**
 * @returns {typeof import('node:http2')}
 */
function getHttp2() {
    if (!isNodejsRuntime()) {
        throw new Error('HTTP/2 Node client is only available in Node.js runtime.')
    }
    if (!http2) {
        http2 = requireDynamic('node:http2')
    }
    return /** @type {typeof import('node:http2')} */ (http2)
}

/**
 * @param {Uint8Array} value
 * @returns {Buffer}
 */
function toBuffer(value) {
    if (Buffer.isBuffer(value)) {
        return value
    }
    if (value?.buffer && typeof value.byteOffset === 'number') {
        return Buffer.from(value.buffer, value.byteOffset, value.byteLength)
    }
    return Buffer.from(value)
}

/**
 * @param {string} message
 * @param {boolean} [connectionLevel]
 * @returns {Error & { transientHttp2?: boolean, connectionLevel?: boolean }}
 */
function createTransientError(message, connectionLevel = false) {
    const error = /** @type {Error & { transientHttp2?: boolean, connectionLevel?: boolean }} */ (
        new Error(message)
    )
    error.transientHttp2 = true
    error.connectionLevel = connectionLevel
    return error
}

/**
 * @param {Http2Client} client
 * @returns {boolean}
 */
function isSessionUsable(client) {
    return Boolean(client?.session && !client.session.closed && !client.session.destroyed && !client.disposed)
}

/**
 * @param {unknown} error
 * @returns {boolean}
 */
function isConnectionLevelHttp2Error(error) {
    if (/** @type {{ connectionLevel?: boolean }} */ (error)?.connectionLevel) {
        return true
    }
    const code = /** @type {{ code?: string }} */ (error)?.code
    return ['ECONNRESET', 'ECONNREFUSED', 'EPIPE', 'ETIMEDOUT', 'ERR_HTTP2_GOAWAY_SESSION', 'ERR_HTTP2_INVALID_SESSION'].includes(
        String(code)
    )
}

/**
 * @param {unknown} error
 * @returns {boolean}
 */
function isTransientHttp2Error(error) {
    if (/** @type {{ transientHttp2?: boolean }} */ (error)?.transientHttp2) {
        return true
    }
    const code = /** @type {{ code?: string }} */ (error)?.code
    return [
        'ECONNRESET',
        'ECONNREFUSED',
        'EPIPE',
        'ETIMEDOUT',
        'ERR_HTTP2_GOAWAY_SESSION',
        'ERR_HTTP2_INVALID_SESSION',
        'ERR_HTTP2_STREAM_CANCEL',
    ].includes(String(code))
}

/**
 * @param {unknown} error
 * @returns {string}
 */
function getErrorMessage(error) {
    return error instanceof Error ? error.message : String(error)
}

export { Http2Client }
