// @ts-check

const WebSocketState = /** @type {const} */ ({
    OPEN: 'open',
    CLOSE: 'close',
    ERROR: 'error',
    MESSAGE: 'message',
})

/** @type {typeof WebSocket | null} */
let WsClient = null
if (isBrowserRuntime() && typeof globalThis.WebSocket !== 'undefined') {
    WsClient = globalThis.WebSocket
}

/**
 * @typedef {object} Options
 * @property {boolean} [isDisconnectedAfterMessage]
 */

/** @type {Record<string, WebSocket>} */
export const clients = {}

/** @type {Record<string, Array<{resolve: Function, reject: Function, messageArray: Uint8Array}>>} */
export const messageQueue = {}

/** @type {Record<string, boolean>} */
export const processingQueues = {}

const MAX_ATTEMPTS = 2
const DEFAULT_CONNECT_TIMEOUT_SECONDS = 3
const DEFAULT_CONNECT_TIMEOUT_MS = DEFAULT_CONNECT_TIMEOUT_SECONDS * 1000
const DEFAULT_RESPONSE_TIMEOUT_SECONDS = 180
const DEFAULT_RESPONSE_TIMEOUT_MS = DEFAULT_RESPONSE_TIMEOUT_SECONDS * 1000

/**
 * WebSocketClient class that handles WebSocket connection, message sending, and automatic disconnection.
 */
class WebSocketClientBrowser {
    /**
     * @param {string} url
     * @param {Options} [options]
     */
    constructor(url, options) {
        /** @type {string} */
        this.url = url

        /** @type {boolean} */
        this.isDisconnectedAfterMessage = options?.isDisconnectedAfterMessage ?? false
    }

    /** @type {WebSocket | null} */
    get instance() {
        return clients[this.url] || null
    }

    get isConnected() {
        const wsClient = getWebSocketClient()
        return this.instance && wsClient ? this.instance.readyState === wsClient.OPEN : false
    }

    /**
     * Sends messageArray through websocket connection with guaranteed order preservation
     * @async
     * @param {Uint8Array} messageArray
     * @returns {Promise<Uint8Array>}
     */
    send(messageArray) {
        if (messageArray == null) {
            return Promise.reject(new Error('messageArray must not be null or undefined'))
        }

        return new Promise((resolve, reject) => {
            if (!messageQueue[this.url]) {
                messageQueue[this.url] = []
            }
            messageQueue[this.url].push({ resolve, reject, messageArray })

            this._processMessage()
        })
    }

    /**
     * Processes message queue sequentially to maintain order
     * @private
     * @async
     */
    async _processMessage() {
        if (processingQueues[this.url]) {
            return
        }
        processingQueues[this.url] = true

        try {
            while (messageQueue[this.url] && messageQueue[this.url].length > 0) {
                const item = messageQueue[this.url].shift()
                if (!item) break

                const { resolve, reject, messageArray } = item
                try {
                    const response = await this._sendWithRetry(messageArray)
                    resolve(response)
                } catch (error) {
                    reject(error)
                }
            }
        } finally {
            processingQueues[this.url] = false
        }
    }

    /**
     * @private
     * @async
     * @param {Uint8Array} messageArray
     * @returns {Promise<Uint8Array>}
     */
    async _sendWithRetry(messageArray) {
        let lastError = null

        for (let attempt = 0; attempt < MAX_ATTEMPTS; attempt++) {
            try {
                return await this._sendSingle(messageArray)
            } catch (error) {
                lastError = error
                if (!isTransientWebSocketError(error)) {
                    // Evict desynced/broken connection after final failure (bug 32346).
                    this._closeCachedClientForRetry()
                    throw error
                }
                if (attempt === MAX_ATTEMPTS - 1) {
                    break
                }
                this._closeCachedClientForRetry()
            }
        }

        // Evict desynced/broken connection after final failure (bug 32346).
        this._closeCachedClientForRetry()
        throw new Error(
            `WebSocket send to ${this.url} failed after ${MAX_ATTEMPTS} attempts. Last error: ${getErrorMessage(lastError)}`
        )
    }

    /**
     * Sends a single message through websocket connection
     * @private
     * @async
     * @param {Uint8Array} messageArray
     * @returns {Promise<Uint8Array>}
     */
    _sendSingle(messageArray) {
        return new Promise((resolve, reject) => {
            const client = this.instance
            if (client && this.isConnected) {
                this._sendMessage(client, messageArray, resolve, reject)
            } else {
                this._connect()
                    .then((ws) => {
                        this._sendMessage(ws, messageArray, resolve, reject)
                    })
                    .catch(reject)
            }
        })
    }

    /**
     * Disconnects the WebSocket by terminating the connection and cleans up queues.
     */
    disconnect() {
        const client = this.instance
        if (client) {
            client.close()
            delete clients[this.url]
        }

        if (messageQueue[this.url]) {
            messageQueue[this.url].forEach(({ reject }) => {
                reject(
                    new Error(
                        `WebSocket to ${this.url} was disconnected. The connection was closed before the operation completed.`
                    )
                )
            })
            delete messageQueue[this.url]
        }
        delete processingQueues[this.url]
    }

    /**
     * @private
     */
    _closeCachedClientForRetry() {
        const client = this.instance
        if (!client) {
            return
        }
        try {
            client.close()
        } catch {
            // ignore close errors during disconnect
        }
        delete clients[this.url]
    }

    /**
     * Connects to the WebSocket server.
     * @private
     * @async
     * @returns {Promise<WebSocket>}
     */
    _connect() {
        return new Promise((resolve, reject) => {
            const wsClient = getWebSocketClient()
            if (!wsClient) {
                return reject(
                    new Error(
                        `WebSocket connection to ${this.url} failed: WebSocket API is not available in this environment. ` +
                            'Ensure the code runs in a browser or environment that supports WebSocket.'
                    )
                )
            }

            let client = clients[this.url]
            if (!client) {
                client = new wsClient(this.url)
                client.binaryType = 'arraybuffer'
                clients[this.url] = client
            }

            const connectTimeout = setTimeout(() => {
                client.removeEventListener(WebSocketState.OPEN, handleOpen)
                client.removeEventListener(WebSocketState.ERROR, handleError)
                client.removeEventListener(WebSocketState.CLOSE, handleClose)
                reject(
                    new Error(
                        `WebSocket connection to ${this.url} timed out after ${DEFAULT_CONNECT_TIMEOUT_SECONDS} seconds.`
                    )
                )
            }, DEFAULT_CONNECT_TIMEOUT_MS)

            const wrapReject = (/** @type {Event | Error | unknown} */ err) => {
                clearTimeout(connectTimeout)
                const msg =
                    err instanceof Error
                        ? err.message
                        : err instanceof Event && err.type
                          ? `Event: ${err.type}`
                          : String(err)
                const wrapped = new Error(
                    `WebSocket connection to ${this.url} failed: ${msg}. ` +
                        'Check that the server is running, the URL is correct (ws:// or wss://), ' +
                        'and that no firewall, CORS, or proxy is blocking the connection.'
                )
                if (err instanceof Error && 'cause' in Error.prototype) {
                    const errorWithCause = /** @type {Error & { cause?: unknown }} */ (wrapped)
                    errorWithCause.cause = err
                }
                reject(wrapped)
            }

            const handleOpen = () => {
                clearTimeout(connectTimeout)
                resolve(client)
            }
            const handleError = (/** @type {Event} */ e) => wrapReject(e)
            const handleClose = () => {
                clearTimeout(connectTimeout)
                reject(
                    new Error(
                        `WebSocket connection to ${this.url} was closed before it could be established. ` +
                            'The server may have refused the connection or a network error occurred. ' +
                            'Check that the server is running and the URL is correct.'
                    )
                )
            }

            client.addEventListener(WebSocketState.OPEN, handleOpen)
            client.addEventListener(WebSocketState.ERROR, handleError)
            client.addEventListener(WebSocketState.CLOSE, handleClose)
        })
    }

    /**
     * Sends the data to the WebSocket server and listens for a response.
     * @private
     * @param {WebSocket} client
     * @param {Uint8Array} data
     * @param {(value: Uint8Array) => void} resolve
     * @param {(reason?: any) => void} reject
     */
    _sendMessage(client, data, resolve, reject) {
        try {
            const payload = /** @type {ArrayBuffer} */ (
                data.buffer.slice(data.byteOffset, data.byteOffset + data.byteLength)
            )
            client.send(payload)

            /** @type {ReturnType<typeof setTimeout>} */
            let responseTimeout
            let settled = false

            const cleanup = () => {
                clearTimeout(responseTimeout)
                client.removeEventListener(WebSocketState.MESSAGE, handleMessage)
                client.removeEventListener(WebSocketState.ERROR, handleError)
                client.removeEventListener(WebSocketState.CLOSE, handleClose)
            }

            const fail = (/** @type {Error} */ error) => {
                if (settled) {
                    return
                }
                settled = true
                cleanup()
                reject(error)
            }

            const handleMessage = (/** @type {any} */ message) => {
                if (settled) {
                    return
                }
                if (!message?.data) {
                    return fail(
                        new Error(
                            `WebSocket to ${this.url}: invalid message received (no data). The server response may be malformed.`
                        )
                    )
                }
                settled = true
                cleanup()

                const byteArray = new Uint8Array(message?.data)
                resolve(byteArray)

                if (this.isDisconnectedAfterMessage) {
                    this.disconnect()
                }
            }

            const handleError = (/** @type {unknown} */ error) => {
                fail(
                    new Error(
                        `WebSocket receive from ${this.url} failed while waiting for response: ${getErrorMessage(error)}`
                    )
                )
            }

            const handleClose = () => {
                fail(
                    new Error(
                        `WebSocket connection to ${this.url} was closed by the remote endpoint while waiting for response. ` +
                            'The server may have shut down or closed the connection.'
                    )
                )
            }

            responseTimeout = setTimeout(() => {
                fail(
                    new Error(
                        `WebSocket receive from ${this.url} timed out after ${DEFAULT_RESPONSE_TIMEOUT_SECONDS} seconds.`
                    )
                )
            }, DEFAULT_RESPONSE_TIMEOUT_MS)

            client.addEventListener(WebSocketState.MESSAGE, handleMessage)
            client.addEventListener(WebSocketState.ERROR, handleError)
            client.addEventListener(WebSocketState.CLOSE, handleClose)
        } catch (err) {
            reject(err)
        }
    }
}

/**
 * @param {unknown} error
 * @returns {boolean}
 */
function isTransientWebSocketError(error) {
    if (!(error instanceof Error)) {
        return true
    }
    return !/messageArray must not be null or undefined/.test(error.message)
}

/**
 * @param {unknown} error
 * @returns {string}
 */
function getErrorMessage(error) {
    return error instanceof Error ? error.message : String(error)
}

/**
 * Resolve lazily so tests and browser-like runtimes can install global WebSocket
 * before the first connection, even if it wasn't present at module import time.
 * @returns {typeof WebSocket | null}
 */
function getWebSocketClient() {
    if (WsClient) {
        return WsClient
    }
    if (isBrowserRuntime() && typeof globalThis.WebSocket !== 'undefined') {
        WsClient = globalThis.WebSocket
        return WsClient
    }
    if (typeof globalThis.WebSocket !== 'undefined') {
        WsClient = globalThis.WebSocket
        return WsClient
    }
    return null
}

/**
 * Keep browser runtime detection local to avoid importing Node-only helpers.
 * @returns {boolean}
 */
function isBrowserRuntime() {
    return typeof window !== 'undefined' && typeof window.document !== 'undefined'
}

export { WebSocketClientBrowser }
