// @ts-check
import { generateGUID } from '../../utils/guid/generateGuid.js'

/**
 * A cache for storing and retrieving delegates.
 *
 * Node.js is single-threaded, so a real mutex isn't needed here: `addDelegate`
 * and `getDelegate` are fully synchronous (no `await`/Promise boundaries), so
 * the JS event loop can never interleave two mutations of the underlying
 * `Map`. Only one instance of this class is ever created (`delegatesCacheInstance`
 * below), matching the singleton lifecycle of the locked Python
 * `DelegatesCache`. If an async method is ever added, guard its critical
 * section with an explicit lock instead of relying on this invariant.
 */
class DelegatesCache {
    cache = new Map()

    /**
     * Adds a delegate to the cache and returns its unique ID.
     * @param {Function} delegateInstance - The delegate function to store.
     * @returns {string} The unique ID for the delegate.
     */
    addDelegate(delegateInstance) {
        const delegateId = generateGUID()
        this.cache.set(delegateId, delegateInstance)
        return delegateId
    }

    /**
     * Retrieves a delegate by its unique ID.
     * @param {string} delegateId - The unique ID of the delegate.
     * @returns {Function} The delegate function.
     * @throws {Error} If the delegate is not found.
     */
    getDelegate(delegateId) {
        const delegateInstance = this.cache.get(delegateId)
        if (!delegateInstance) {
            throw new Error('Delegate not found')
        }
        return delegateInstance
    }
}

const delegatesCacheInstance = new DelegatesCache()

export { delegatesCacheInstance }
