// @ts-check

import { getRequire } from '../../utils/Runtime.js'
import { AbstractHandler } from './AbstractHandler.js'

/**
 * @typedef {import('../../utils/Command.js').Command} Command
 * @typedef {'cjs' | 'esm'} ModuleFormat
 */

/** @type {typeof import('fs').existsSync | null} */
let _existsSync = null

/** @type {typeof import('fs').readFileSync | null} */
let _readFileSync = null

/** @type {typeof import('fs').statSync | null} */
let _statSync = null

/** @type {typeof import('path').resolve | null} */
let _resolve = null

/** @type {typeof import('path').join | null} */
let _join = null

/** @type {typeof import('path').dirname | null} */
let _dirname = null

/** @type {typeof import('vm').Script | null} */
let _vmScript = null

/** @type {typeof import('vm').SourceTextModule | null} */
let _vmSourceTextModule = null

/** @type {import('url').pathToFileURL | null} */
let _pathToFileURL = null

const requireDynamic = getRequire(import.meta.url)

function ensureDependencies() {
    if (!_existsSync || !_readFileSync || !_statSync) {
        const { existsSync, readFileSync, statSync } = requireDynamic('fs')
        _existsSync = existsSync
        _readFileSync = readFileSync
        _statSync = statSync
    }
    if (!_resolve || !_join || !_dirname) {
        const { resolve, join, dirname } = requireDynamic('path')
        _resolve = resolve
        _join = join
        _dirname = dirname
    }
    if (!_pathToFileURL) {
        const { pathToFileURL } = requireDynamic('url')
        _pathToFileURL = pathToFileURL
    }
}

/**
 * @param {string} packageJsonPath
 * @returns {Record<string, unknown>}
 */
function readPackageJson(packageJsonPath) {
    ensureDependencies()
    try {
        return JSON.parse(_readFileSync ? _readFileSync(packageJsonPath, 'utf8') : '')
    } catch (error) {
        throw new Error(`Cannot load module: Cannot parse package.json: ${packageJsonPath}\n${error}`)
    }
}

/**
 * @param {Record<string, unknown>} moduleNamespace
 * @returns {Record<string, unknown>}
 */
function normalizeEsmExports(moduleNamespace) {
    /** @type {Record<string, unknown>} */
    const moduleExports = { ...moduleNamespace }

    const defaultExport = moduleNamespace.default
    if (
        defaultExport !== undefined &&
        (typeof defaultExport === 'function' || typeof defaultExport === 'object') &&
        defaultExport !== null &&
        'name' in defaultExport &&
        typeof defaultExport.name === 'string' &&
        defaultExport.name.length > 0 &&
        moduleExports[defaultExport.name] === undefined
    ) {
        moduleExports[defaultExport.name] = defaultExport
    }

    return moduleExports
}

/**
 * @param {string} filePath
 * @param {string | null} [packageRootDir]
 * @returns {ModuleFormat}
 */
function detectModuleFormat(filePath, packageRootDir = null) {
    ensureDependencies()

    if (/\.mjs$/i.test(filePath)) {
        return 'esm'
    }
    if (/\.cjs$/i.test(filePath)) {
        return 'cjs'
    }

    if (packageRootDir) {
        const localPackageJsonPath = _join
            ? _join(packageRootDir, 'package.json')
            : `${packageRootDir}/package.json`
        if (_existsSync?.(localPackageJsonPath)) {
            try {
                const packageJson = readPackageJson(localPackageJsonPath)
                return packageJson.type === 'module' ? 'esm' : 'cjs'
            } catch {
                return 'cjs'
            }
        }

        // Loaded directory is the package boundary — without local package.json, .js is CommonJS.
        return 'cjs'
    }

    let searchDir = _dirname ? _dirname(filePath) : null
    while (searchDir) {
        const packageJsonPath = _join ? _join(searchDir, 'package.json') : `${searchDir}/package.json`
        if (_existsSync?.(packageJsonPath)) {
            try {
                const packageJson = readPackageJson(packageJsonPath)
                return packageJson.type === 'module' ? 'esm' : 'cjs'
            } catch {
                return 'cjs'
            }
        }

        const parentDir = _dirname ? _dirname(searchDir) : null
        if (!parentDir || parentDir === searchDir) {
            break
        }
        searchDir = parentDir
    }

    return 'cjs'
}

class LoadLibraryHandler extends AbstractHandler {
    requiredParametersCount = 1
    // Shared across all instances (mirrors the JVM/.NET static loaded-library
    // sets). `process()` is fully synchronous (no `await`/Promise boundaries)
    // so the JS event loop can never interleave two mutations of this array;
    // if that ever changes, guard reads/writes with an explicit lock.
    /** @type {string[]} */
    static loadedLibraries = []
    /** @type {Map<string, unknown>} */
    static loadedModuleExports = new Map()

    /**
     * @param {Command} command
     * @returns {number | Promise<number>}
     */
    process(command) {
        this.validate(command, this.requiredParametersCount, this.constructor.name)

        const { payload } = command
        const [lib] = payload

        if (!lib) {
            throw new Error('Cannot load module: Library path is required but was not provided')
        }

        ensureDependencies()

        const absolutePath = _resolve ? _resolve(lib) : lib
        const existingPath = [lib, absolutePath].find((p) => _existsSync?.(p))

        if (!existingPath) {
            throw new Error(`Cannot load module: Library not found: ${lib}`)
        }

        let modulePath = existingPath
        /** @type {string | null} */
        let packageRootDir = null

        if (_statSync?.(existingPath).isDirectory()) {
            packageRootDir = existingPath
            modulePath = this.#resolveModulePathFromDirectory(existingPath)
        } else if (/[\\/]package\.json$/i.test(existingPath)) {
            if (!_dirname) {
                throw new Error('Cannot load module: Unable to resolve package.json directory')
            }
            packageRootDir = _dirname(existingPath)
            modulePath = this.#resolveModulePathFromPackageJson(existingPath, packageRootDir)
        }

        const normalizedPath = _resolve ? _resolve(modulePath) : modulePath
        const moduleFormat = detectModuleFormat(normalizedPath, packageRootDir)

        if (moduleFormat === 'cjs') {
            this.#validateCommonJsSyntax(normalizedPath)
        } else {
            this.#validateEsmSyntax(normalizedPath)
        }

        if (LoadLibraryHandler.loadedLibraries.includes(normalizedPath)) {
            return 0
        }

        const libraryName = this.#getLibraryName(normalizedPath)

        if (moduleFormat === 'esm') {
            return this.#loadEsmModule(normalizedPath, libraryName)
        }

        return this.#loadCommonJsModule(normalizedPath, libraryName, packageRootDir)
    }

    /**
     * @param {string} normalizedPath
     * @returns {string}
     */
    #getLibraryName(normalizedPath) {
        const fileName = normalizedPath.split(/[/\\]/).pop() ?? normalizedPath
        return fileName.replace(/\.(js|mjs|cjs)$/i, '')
    }

    /**
     * @param {string} packageRootDir
     * @returns {string}
     */
    #resolveModulePathFromDirectory(packageRootDir) {
        const packageJsonPath = _join
            ? _join(packageRootDir, 'package.json')
            : `${packageRootDir}/package.json`

        if (_existsSync?.(packageJsonPath)) {
            return this.#resolveModulePathFromPackageJson(packageJsonPath, packageRootDir)
        }

        for (const entryFile of ['index.js', 'index.mjs', 'index.cjs']) {
            const entryPath = _join ? _join(packageRootDir, entryFile) : `${packageRootDir}/${entryFile}`
            if (_existsSync?.(entryPath)) {
                return entryPath
            }
        }

        throw new Error(
            `Cannot load module: No entry point found in directory: ${packageRootDir}. ` +
                'Expected package.json with "main" or index.js/index.mjs/index.cjs.'
        )
    }

    /**
     * @param {string} packageJsonPath
     * @param {string} packageRootDir
     * @returns {string}
     */
    #resolveModulePathFromPackageJson(packageJsonPath, packageRootDir) {
        const packageJson = readPackageJson(packageJsonPath)

        if (!packageJson.main || typeof packageJson.main !== 'string') {
            throw new Error(`Cannot load module: Missing "main" entry in package.json: ${packageJsonPath}`)
        }

        const resolvedModulePath = _join
            ? _join(packageRootDir, packageJson.main)
            : `${packageRootDir}/${packageJson.main}`
        if (!_existsSync?.(resolvedModulePath)) {
            throw new Error(`Cannot load module: Entry point not found: ${resolvedModulePath}`)
        }

        return resolvedModulePath
    }

    /**
     * @param {string} filePath
     */
    #validateEsmSyntax(filePath) {
        if (!/\.(js|mjs)$/i.test(filePath)) {
            return
        }

        if (!_vmSourceTextModule) {
            const { SourceTextModule } = requireDynamic('vm')
            _vmSourceTextModule = SourceTextModule ?? null
        }

        if (!_vmSourceTextModule) {
            return
        }

        try {
            const sourceCode = _readFileSync ? _readFileSync(filePath, 'utf8') : ''
            new _vmSourceTextModule(sourceCode, { identifier: filePath })
        } catch (error) {
            throw new Error(`Cannot load module: JavaScript syntax error in file: ${filePath}\n${error}`)
        }
    }

    /**
     * @param {string} filePath
     */
    #validateCommonJsSyntax(filePath) {
        if (!/\.(js|cjs)$/i.test(filePath)) {
            return
        }

        if (!_vmScript) {
            const { Script } = requireDynamic('vm')
            _vmScript = Script
        }

        try {
            const sourceCode = _readFileSync ? _readFileSync(filePath, 'utf8') : ''
            if (_vmScript) {
                new _vmScript(sourceCode, { filename: filePath })
            }
        } catch (error) {
            throw new Error(`Cannot load module: JavaScript syntax error in file: ${filePath}\n${error}`)
        }
    }

    /**
     * @param {string} normalizedPath
     * @param {string} libraryName
     * @param {string | null} packageRootDir
     * @returns {number}
     */
    #loadCommonJsModule(normalizedPath, libraryName, packageRootDir) {
        let moduleExports
        try {
            moduleExports = this.#shouldLoadCommonJsViaVm(normalizedPath, packageRootDir)
                ? this.#loadCommonJsViaVm(normalizedPath)
                : requireDynamic(normalizedPath)
        } catch (error) {
            if (this.#isCommonJsScopeError(error)) {
                moduleExports = this.#loadCommonJsViaVm(normalizedPath)
            } else {
                throw new Error('Cannot load module: ' + normalizedPath + '\n' + error)
            }
        }

        this.#registerModuleExports(normalizedPath, libraryName, moduleExports)
        return 0
    }

    /**
     * @param {string} filePath
     * @param {string | null} packageRootDir
     * @returns {boolean}
     */
    #shouldLoadCommonJsViaVm(filePath, packageRootDir) {
        if (!/\.js$/i.test(filePath) || /\.cjs$/i.test(filePath)) {
            return false
        }

        if (!packageRootDir) {
            return false
        }

        const localPackageJsonPath = _join
            ? _join(packageRootDir, 'package.json')
            : `${packageRootDir}/package.json`

        return !_existsSync?.(localPackageJsonPath)
    }

    /**
     * @param {unknown} error
     * @returns {boolean}
     */
    #isCommonJsScopeError(error) {
        if (!(error instanceof Error)) {
            return false
        }

        const { message } = error
        return (
            message.includes('module is not defined') ||
            message.includes('ERR_REQUIRE_ESM') ||
            message.includes('require() of ES Module')
        )
    }

    /**
     * @param {string} filePath
     * @returns {unknown}
     */
    #loadCommonJsViaVm(filePath) {
        if (!_vmScript) {
            const { Script } = requireDynamic('vm')
            _vmScript = Script
        }

        const sourceCode = _readFileSync ? _readFileSync(filePath, 'utf8') : ''
        const moduleDir = _dirname ? _dirname(filePath) : ''
        /** @type {{ exports: Record<string, unknown> }} */
        const cjsModule = { exports: {} }

        const wrappedSource = `(function (exports, require, module, __filename, __dirname) {\n${sourceCode}\n})`
        const script = _vmScript ? new _vmScript(wrappedSource, { filename: filePath }) : null
        const runModule = script?.runInThisContext()
        if (typeof runModule !== 'function') {
            throw new Error(`Cannot load module: Failed to execute CommonJS file: ${filePath}`)
        }

        runModule.call(cjsModule.exports, cjsModule.exports, requireDynamic, cjsModule, filePath, moduleDir)

        return cjsModule.exports
    }

    /**
     * @param {string} normalizedPath
     * @param {string} libraryName
     * @returns {Promise<number>}
     */
    async #loadEsmModule(normalizedPath, libraryName) {
        let moduleExports
        try {
            const moduleUrl = _pathToFileURL ? _pathToFileURL(normalizedPath).href : normalizedPath
            const moduleNamespace = await import(moduleUrl)
            moduleExports = normalizeEsmExports(moduleNamespace)
        } catch (error) {
            throw new Error('Cannot load module: ' + normalizedPath + '\n' + error)
        }

        this.#registerModuleExports(normalizedPath, libraryName, moduleExports)
        return 0
    }

    /**
     * @param {string} normalizedPath
     * @param {string} libraryName
     * @param {unknown} moduleExports
     */
    #registerModuleExports(normalizedPath, libraryName, moduleExports) {
        LoadLibraryHandler.loadedLibraries.push(normalizedPath)
        LoadLibraryHandler.loadedModuleExports.set(normalizedPath, moduleExports)

        // @ts-expect-error
        global[libraryName] = moduleExports

        if (moduleExports && typeof moduleExports === 'object') {
            for (const [key, value] of Object.entries(moduleExports)) {
                // @ts-expect-error
                global[key] = value
            }
        }
    }

    getLoadedLibraries() {
        return LoadLibraryHandler.loadedLibraries
    }

    /**
     * @returns {Map<string, unknown>}
     */
    static getLoadedModuleExports() {
        return LoadLibraryHandler.loadedModuleExports
    }
}

export { LoadLibraryHandler }
