// @ts-check
import { Buffer } from 'buffer'

/**
 * Mutable writer state created by {@link BufferWriter.create}.
 * @typedef {{ buffer: Buffer, length: number }} BufferWriterState
 */

/**
 * Static growable byte-buffer writer. Operate on state from {@link BufferWriter.create}.
 */
class BufferWriter {
    constructor() {
        throw new Error('BufferWriter is a static utility class and cannot be instantiated')
    }

    /**
     * @param {number} [initialCapacity]
     * @returns {BufferWriterState}
     */
    static create(initialCapacity = 256) {
        return {
            buffer: Buffer.alloc(Math.max(initialCapacity, 1)),
            length: 0,
        }
    }

    /**
     * @param {BufferWriterState} writer
     * @param {number} additionalBytes
     */
    static ensureCapacity(writer, additionalBytes) {
        const required = writer.length + additionalBytes
        if (required <= writer.buffer.length) return
        let newCapacity = writer.buffer.length * 2
        while (newCapacity < required) {
            newCapacity *= 2
        }
        const newBuffer = Buffer.alloc(newCapacity)
        writer.buffer.copy(newBuffer, 0, 0, writer.length)
        writer.buffer = newBuffer
    }

    /**
     * @param {BufferWriterState} writer
     * @param {number} value
     */
    static writeUInt8(writer, value) {
        BufferWriter.ensureCapacity(writer, 1)
        writer.buffer.writeUInt8(value, writer.length)
        writer.length += 1
    }

    /**
     * @param {BufferWriterState} writer
     * @param {number} value
     */
    static writeInt32LE(writer, value) {
        BufferWriter.ensureCapacity(writer, 4)
        writer.buffer.writeInt32LE(value, writer.length)
        writer.length += 4
    }

    /**
     * @param {BufferWriterState} writer
     * @param {number} value
     */
    static writeUInt32LE(writer, value) {
        BufferWriter.ensureCapacity(writer, 4)
        writer.buffer.writeUInt32LE(value, writer.length)
        writer.length += 4
    }

    /**
     * @param {BufferWriterState} writer
     * @param {number} value
     */
    static writeFloatLE(writer, value) {
        BufferWriter.ensureCapacity(writer, 4)
        writer.buffer.writeFloatLE(value, writer.length)
        writer.length += 4
    }

    /**
     * @param {BufferWriterState} writer
     * @param {number} value
     */
    static writeDoubleLE(writer, value) {
        BufferWriter.ensureCapacity(writer, 8)
        writer.buffer.writeDoubleLE(value, writer.length)
        writer.length += 8
    }

    /**
     * @param {BufferWriterState} writer
     * @param {bigint} value
     */
    static writeBigInt64LE(writer, value) {
        BufferWriter.ensureCapacity(writer, 8)
        writer.buffer.writeBigInt64LE(value, writer.length)
        writer.length += 8
    }

    /**
     * @param {BufferWriterState} writer
     * @param {bigint} value
     */
    static writeBigUInt64LE(writer, value) {
        BufferWriter.ensureCapacity(writer, 8)
        writer.buffer.writeBigUInt64LE(value, writer.length)
        writer.length += 8
    }

    /**
     * @param {BufferWriterState} writer
     * @param {Uint8Array} bytes
     */
    static writeBytes(writer, bytes) {
        BufferWriter.ensureCapacity(writer, bytes.length)
        writer.buffer.set(bytes, writer.length)
        writer.length += bytes.length
    }

    /**
     * @param {BufferWriterState} writer
     * @returns {Uint8Array}
     */
    static toUint8Array(writer) {
        return writer.buffer.subarray(0, writer.length)
    }
}

export { BufferWriter }
