// @ts-check
import { Command } from '../../utils/Command.js'
import { Buffer } from 'buffer'
import { StringEncodingMode } from '../../utils/StringEncodingMode.js'

/**
 * Wraps bytes as a Buffer view without copying when the input is already a
 * Buffer/Uint8Array. Falls back to a copy for plain arrays.
 * @param {ArrayLike<number>} bytes
 * @returns {Buffer}
 */
function asBuffer(bytes) {
    if (Buffer.isBuffer(bytes)) return bytes
    if (bytes instanceof Uint8Array) return Buffer.from(bytes.buffer, bytes.byteOffset, bytes.byteLength)
    return Buffer.from(bytes)
}

export class TypeDeserializer {
    constructor() {
        throw new Error('TypeDeserializer is a static utility class and cannot be instantiated')
    }

    /**
     * @param {Uint8Array} encodedCommand
     * @returns {Command}
     */
    static deserializeCommand(encodedCommand) {
        return new Command(encodedCommand[0], encodedCommand[1], [])
    }

    /**
     * @param {number} stringEncodingMode
     * @param {ArrayLike<number>} encodedString
     * @param {number} [offset]
     * @param {number} [length]
     */
    static deserializeString(
        stringEncodingMode,
        encodedString,
        offset = 0,
        length = encodedString.length - offset
    ) {
        switch (stringEncodingMode) {
            case StringEncodingMode.ASCII: {
                let result = ''
                for (let i = 0; i < length; i++) {
                    result += String.fromCharCode(encodedString[offset + i])
                }
                return result
            }
            case StringEncodingMode.UTF8: {
                const decoder = new TextDecoder('UTF-8')
                const view =
                    encodedString instanceof Uint8Array
                        ? encodedString.subarray(offset, offset + length)
                        : Uint8Array.from(encodedString).subarray(offset, offset + length)
                return decoder.decode(view)
            }
            case StringEncodingMode.UTF16: {
                let str = ''
                for (let i = 0; i < length; i += 2) {
                    str += String.fromCharCode(
                        encodedString[offset + i] + 256 * encodedString[offset + i + 1]
                    )
                }
                return str
            }
            case StringEncodingMode.UTF32:
                throw 'Type utf32-encoded string not supported in JavaScript'
            default:
                throw 'Unknown string encoding - not supported in JavaScript'
        }
    }

    /**
     * @param {ArrayLike<number>} bytes
     * @param {number} [offset]
     */
    static deserializeInt(bytes, offset = 0) {
        return (
            (bytes[offset] & 0xff) |
            ((bytes[offset + 1] & 0xff) << 8) |
            ((bytes[offset + 2] & 0xff) << 16) |
            ((bytes[offset + 3] & 0xff) << 24)
        )
    }

    /**
     * @param {ArrayLike<number>} bytes
     * @param {number} [offset]
     */
    static deserializeBool(bytes, offset = 0) {
        return bytes[offset] === 1
    }

    /**
     * @param {ArrayLike<number>} bytes
     * @param {number} [offset]
     */
    static deserializeFloat(bytes, offset = 0) {
        return asBuffer(bytes).readFloatLE(offset)
    }

    /**
     * @param {ArrayLike<number>} bytes
     * @param {number} [offset]
     */
    static deserializeByte(bytes, offset = 0) {
        return bytes[offset]
    }

    /**
     * @param {ArrayLike<number>} bytes
     * @param {number} [offset]
     */
    static deserializeChar(bytes, offset = 0) {
        return bytes[offset]
    }

    /**
     * @param {ArrayLike<number>} bytes
     * @param {number} [offset]
     */
    static deserializeLongLong(bytes, offset = 0) {
        return asBuffer(bytes).readBigInt64LE(offset)
    }

    /**
     * @param {ArrayLike<number>} bytes
     * @param {number} [offset]
     */
    static deserializeDouble(bytes, offset = 0) {
        return asBuffer(bytes).readDoubleLE(offset)
    }

    /**
     * @param {ArrayLike<number>} bytes
     * @param {number} [offset]
     */
    static deserializeULLong(bytes, offset = 0) {
        return asBuffer(bytes).readBigUInt64LE(offset)
    }

    /**
     * @param {ArrayLike<number>} bytes
     * @param {number} [offset]
     */
    static deserializeUInt(bytes, offset = 0) {
        return asBuffer(bytes).readUIntLE(offset, 4)
    }

    static deserializeNull(encodedNull = null) {
        return null
    }

    static deserializeUndefined(encodedUndefined = null) {
        return undefined
    }
}
