// @ts-check

import { getRequire, isNodejsRuntime } from '../Runtime.js'

/**
 * @typedef {import('../ConnectionType.js').ConnectionType} ConnectionType
 */

const requireDynamic = getRequire(import.meta.url)

/** @type {import('node:async_hooks').AsyncLocalStorage<Record<string, string>> | null} */
let asyncLocalHeadersStore = null

/** @type {Record<string, string>} */
let fallbackThreadLocalHeaders = {}

if (isNodejsRuntime()) {
    try {
        const { AsyncLocalStorage } = requireDynamic('node:async_hooks')
        asyncLocalHeadersStore = new AsyncLocalStorage()
    } catch {
        asyncLocalHeadersStore = null
    }
}

/**
 * @param {Record<string, string>} headers
 * @returns {Record<string, string>}
 */
function normalizeHeaders(headers) {
    /** @type {Record<string, string>} */
    const normalized = {}
    if (!headers) {
        return normalized
    }
    for (const key of Object.keys(headers)) {
        normalized[String(key).trim().toLowerCase()] = String(headers[key]).trim()
    }
    return normalized
}

/**
 * @returns {Record<string, string>}
 */
function readThreadLocalHeaders() {
    if (asyncLocalHeadersStore) {
        const store = asyncLocalHeadersStore.getStore()
        return store ? { ...store } : {}
    }
    return { ...fallbackThreadLocalHeaders }
}

export class IConnectionData {
    constructor() {
        /** @type {Record<string, string>} */
        this._headers = {}
    }

    /**
     * @returns {ConnectionType}
     */
    get connectionType() {
        throw new Error('You have to implement the method connectionType!')
    }

    /**
     * @returns {string}
     */
    get hostname() {
        throw new Error('You have to implement the method hostname!')
    }

    /**
     * @returns {number[]}
     */
    serializeConnectionData() {
        throw new Error('You have to implement the method serializeConnectionData!')
    }

    /**
     * @returns {string}
     */
    toCanonicalKey() {
        let key = this.toString()
        if (Object.keys(this.getHeaders()).length > 0) {
            key += `|h:${this.serializeHeadersForKey()}`
        }
        const config = this.getConfig()
        if (config) {
            key += `|c:${config}`
        }
        return key
    }

    /**
     * @param {Record<string, string>} headers
     */
    setHeaders(headers) {
        this._headers = normalizeHeaders(headers)
    }

    /**
     * @param {Record<string, string>} headers
     */
    setThreadLocalHeaders(headers) {
        const normalizedHeaders = normalizeHeaders(headers)
        if (asyncLocalHeadersStore) {
            asyncLocalHeadersStore.enterWith(normalizedHeaders)
            return
        }
        fallbackThreadLocalHeaders = normalizedHeaders
    }

    /**
     * @returns {Record<string, string>}
     */
    getThreadLocalHeaders() {
        return readThreadLocalHeaders()
    }

    /**
     * @returns {Record<string, string>}
     */
    getHeaders() {
        /** @type {Record<string, string>} */
        const combinedHeaders = { ...this._headers }
        const localHeaders = readThreadLocalHeaders()
        for (const key of Object.keys(localHeaders)) {
            combinedHeaders[key] = localHeaders[key]
        }
        return combinedHeaders
    }

    /**
     * @returns {string}
     */
    getConfig() {
        return ''
    }

    /**
     * @returns {string}
     */
    serializeHeadersForKey() {
        const headers = this.getHeaders()
        const keys = Object.keys(headers).sort()
        return keys.map((key) => `${key}=${headers[key]}`).join(';')
    }

    /**
     * @returns {string}
     */
    toString() {
        switch (this.connectionType) {
            case 0:
                return `inmemory|${this.hostname}`
            case 1:
                return `tcp|${this.hostname}`
            case 2:
                return `websocket|${this.hostname}`
            case 3:
                return `http2|${this.hostname}`
            default:
                return `unknown|${this.hostname}`
        }
    }
}
