// @ts-check
import { WebSocketClient } from '../webSocketClient/WebSocketClient.js'
import { WsConnectionData } from '../../utils/connectionData/WsConnectionData.js'

export class TransmitterWebsocket {
    /**
     * @returns {void}
     */
    static initialize() {}

    /**
     * @returns {void}
     */
    static setConfigSource() {}

    /**
     * @returns {void}
     */
    static activate() {}

    /**
     * @async
     * @param {Uint8Array} messageByteArray
     * @param {WsConnectionData} connectionData
     * @returns {Promise<Uint8Array>} responseByteArray
     */
    static sendCommand(messageByteArray, connectionData) {
        const options = {
            isDisconnectedAfterMessage: false,
        }
        return new WebSocketClient(connectionData, options).send(messageByteArray)
    }
}
