// @ts-check

// Module-scoped state shared by every `TypeCache` instance so the singleton
// pattern below always operates on a single source of truth, mirroring the
// locked pattern used by the Python `TypeCache`. Node.js is single-threaded,
// so a real mutex isn't needed here: every method on this class is fully
// synchronous (no `await`/Promise boundaries), which means the JS event loop
// can never interleave two mutations of `_typeCache`. If an async method is
// ever added, guard its critical section with an explicit lock instead of
// relying on this invariant.
/** @type {string[]} */
const _typeCache = []

/** @type {TypeCache | null} */
let _instance = null

class TypeCache {
    constructor() {
        if (_instance === null) {
            _instance = this
        }
        return _instance
    }

    /**
     * @param {string} typRegex
     */
    cacheType(typRegex) {
        _typeCache.push(typRegex)
    }

    isTypeCacheEmpty() {
        return _typeCache.length === 0
    }

    /**
     * @param {{ name: string }} typeToCheck
     */
    isTypeAllowed(typeToCheck) {
        for (let pattern of _typeCache) {
            if (new RegExp(pattern).test(typeToCheck.name)) {
                return true
            }
        }
        return false
    }

    getCachedTypes() {
        return _typeCache.slice()
    }

    clearCache() {
        _typeCache.length = 0
        return 0
    }
}

export { TypeCache }
