// @ts-check
import { Command } from '../../utils/Command.js'
import { Type } from '../../utils/Type.js'
import { StringEncodingMode } from '../../utils/StringEncodingMode.js'
import { CustomError } from '../../utils/CustomError.js'
import { BufferWriter } from './BufferWriter.js'

/**
 * @typedef {import('./BufferWriter.js').BufferWriterState} BufferWriterState
 */

const encoder = new TextEncoder()

class TypeSerializer {
    constructor() {
        throw new Error('TypeSerializer is a static utility class and cannot be instantiated')
    }

    /**
     * @param {BufferWriterState} writer
     * @param {Command} command
     */
    static writeCommandHeader(writer, command) {
        BufferWriter.writeUInt8(writer, Type.HT_COMMAND)
        BufferWriter.writeInt32LE(writer, command.payload.length)
        BufferWriter.writeUInt8(writer, command.runtimeName)
        BufferWriter.writeUInt8(writer, command.commandType)
    }

    /**
     * @param {BufferWriterState} writer
     * @param {unknown} payload_item
     */
    static writePrimitive(writer, payload_item) {
        if (payload_item === null) {
            TypeSerializer.writeNull(writer)
            return
        }
        if (payload_item === undefined) {
            TypeSerializer.writeUndefined(writer)
            return
        }
        if (payload_item instanceof Command) {
            TypeSerializer.writeCommandHeader(writer, payload_item)
        } else if (typeof payload_item === 'number') {
            if (Number.isInteger(payload_item)) {
                TypeSerializer.writeInt(writer, payload_item)
            } else {
                TypeSerializer.writeDouble(writer, payload_item)
            }
        } else if (typeof payload_item === 'string') {
            TypeSerializer.writeString(writer, payload_item)
        } else if (typeof payload_item === 'boolean') {
            TypeSerializer.writeBool(writer, payload_item)
        } else {
            if (payload_item instanceof Promise) {
                const message =
                    'Unsupported payload item type: ' +
                    (payload_item?.constructor?.name || typeof payload_item) +
                    ' for payload item: ' +
                    payload_item
                throw new CustomError(message, 'HT_PROMISE')
            }
            throw Error(
                'Unsupported payload item type: ' +
                    (payload_item?.constructor?.name || typeof payload_item) +
                    ' for payload item: ' +
                    payload_item
            )
        }
    }

    /**
     * @param {BufferWriterState} writer
     * @param {string} string_value
     */
    static writeString(writer, string_value) {
        const bytes = encoder.encode(string_value)
        BufferWriter.writeUInt8(writer, Type.HT_STRING)
        BufferWriter.writeUInt8(writer, StringEncodingMode.UTF8)
        BufferWriter.writeInt32LE(writer, bytes.length)
        BufferWriter.writeBytes(writer, bytes)
    }

    /**
     * @param {BufferWriterState} writer
     * @param {number} int_value
     */
    static writeInt(writer, int_value) {
        BufferWriter.writeUInt8(writer, Type.HT_INTEGER)
        BufferWriter.writeUInt8(writer, 4)
        BufferWriter.writeInt32LE(writer, int_value)
    }

    /**
     * @param {BufferWriterState} writer
     * @param {boolean} bool_value
     */
    static writeBool(writer, bool_value) {
        BufferWriter.writeUInt8(writer, Type.HT_BOOLEAN)
        BufferWriter.writeUInt8(writer, 1)
        BufferWriter.writeUInt8(writer, bool_value ? 1 : 0)
    }

    /**
     * @param {BufferWriterState} writer
     * @param {number} float_value
     */
    static writeFloat(writer, float_value) {
        BufferWriter.writeUInt8(writer, Type.HT_FLOAT)
        BufferWriter.writeUInt8(writer, 4)
        BufferWriter.writeFloatLE(writer, float_value)
    }

    /**
     * @param {BufferWriterState} writer
     * @param {number} byte_value
     */
    static writeByte(writer, byte_value) {
        BufferWriter.writeUInt8(writer, Type.HT_BYTE)
        BufferWriter.writeUInt8(writer, 1)
        BufferWriter.writeUInt8(writer, byte_value)
    }

    /**
     * @param {BufferWriterState} writer
     * @param {number} char_value
     */
    static writeChar(writer, char_value) {
        BufferWriter.writeUInt8(writer, Type.HT_CHAR)
        BufferWriter.writeUInt8(writer, 1)
        BufferWriter.writeUInt8(writer, char_value)
    }

    /**
     * @param {BufferWriterState} writer
     * @param {number} longlong_value
     */
    static writeLongLong(writer, longlong_value) {
        BufferWriter.writeUInt8(writer, Type.HT_LONG_LONG)
        BufferWriter.writeUInt8(writer, 8)
        BufferWriter.writeBigInt64LE(writer, BigInt(longlong_value))
    }

    /**
     * @param {BufferWriterState} writer
     * @param {number} double_value
     */
    static writeDouble(writer, double_value) {
        BufferWriter.writeUInt8(writer, Type.HT_DOUBLE)
        BufferWriter.writeUInt8(writer, 8)
        BufferWriter.writeDoubleLE(writer, double_value)
    }

    /**
     * @param {BufferWriterState} writer
     * @param {bigint} ullong_value
     */
    static writeULLong(writer, ullong_value) {
        BufferWriter.writeUInt8(writer, Type.HT_UNSIGNED_LONG_LONG)
        BufferWriter.writeUInt8(writer, 8)
        BufferWriter.writeBigUInt64LE(writer, ullong_value)
    }

    /**
     * @param {BufferWriterState} writer
     * @param {number} uint_value
     */
    static writeUInt(writer, uint_value) {
        BufferWriter.writeUInt8(writer, Type.HT_UNSIGNED_INTEGER)
        BufferWriter.writeUInt8(writer, 4)
        BufferWriter.writeUInt32LE(writer, uint_value)
    }

    /**
     * @param {BufferWriterState} writer
     */
    static writeNull(writer) {
        BufferWriter.writeUInt8(writer, Type.HT_NULL)
        BufferWriter.writeUInt8(writer, 1)
        BufferWriter.writeUInt8(writer, 0)
    }

    /**
     * @param {BufferWriterState} writer
     */
    static writeUndefined(writer) {
        BufferWriter.writeUInt8(writer, Type.HT_UNDEFINED)
        BufferWriter.writeUInt8(writer, 1)
        BufferWriter.writeUInt8(writer, 0)
    }
}

export { TypeSerializer }
