// @ts-check

import { AbstractHandler } from './AbstractHandler.js'
import { LoadLibraryHandler } from './LoadLibraryHandler.js'
import { NamespaceCache } from '../namespaceCache/NamespaceCache.js'
import { TypeCache } from '../typeCache/TypeCache.js'
import { ValueTypeParser } from '../valueTypesParser/ValueTypeParser.js'

/**
 * @typedef {import('../../utils/Command.js').Command} Command
 */
class GetTypeHandler extends AbstractHandler {
    constructor() {
        super()
        /** @type {number} */
        this.requiredParametersCount = 1
        /** @type {NamespaceCache} */
        this.namespaceCache = new NamespaceCache()
        /** @type {TypeCache} */
        this.typeCache = new TypeCache()
    }

    /**
     * @param {Command} command
     */
    process(command) {
        try {
            this.validate(command, this.requiredParametersCount, this.constructor.name)
            const { payload } = command
            let typeName = payload[0]
            typeName = typeName.replace('.js', '')
            const typeToReturn = /** @type {any} */ (global)[typeName]
            if (typeToReturn === undefined) {
                let message = `Type ${typeName} not found\n`
                message += 'Available types:\n'
                message += this.getAvailableTypes().join('\n')
                throw new Error(message)
            }

            if (
                ValueTypeParser.isParsableValueTypeByType(typeToReturn) ||
                (this.namespaceCache.isNamespaceCacheEmpty() && this.typeCache.isTypeCacheEmpty()) ||
                this.namespaceCache.isTypeAllowed(typeToReturn) ||
                this.typeCache.isTypeAllowed(typeToReturn)
            ) {
                // continue - type is allowed
            } else {
                let allowed_namespaces = this.namespaceCache.getCachedNamespaces().join(', ')
                let allowed_types = this.typeCache.getCachedTypes().join(', ')
                throw new Error(
                    `Type ${typeToReturn.name} not allowed. \nAllowed namespaces: ${allowed_namespaces}\nAllowed types: ${allowed_types}`
                )
            }

            return typeToReturn
        } catch (error) {
            throw this.process_stack_trace(error, this.constructor.name)
        }
    }

    getAvailableTypes() {
        /** @type {string[]} */
        const availableTypes = []

        for (const moduleExports of LoadLibraryHandler.getLoadedModuleExports().values()) {
            const exportName = getModuleExportName(moduleExports)
            if (exportName) {
                availableTypes.push(exportName)
            }

            if (moduleExports && typeof moduleExports === 'object') {
                for (const key of Object.keys(moduleExports)) {
                    availableTypes.push(key)
                }
            }
        }

        return availableTypes
    }
}

/**
 * @param {unknown} moduleExports
 * @returns {string}
 */
function getModuleExportName(moduleExports) {
    if (typeof moduleExports === 'function') {
        return moduleExports.name ?? ''
    }

    return getObjectExportName(moduleExports)
}

/**
 * @param {unknown} moduleExports
 * @returns {string}
 */
function getObjectExportName(moduleExports) {
    if (
        moduleExports &&
        typeof moduleExports === 'object' &&
        'name' in moduleExports &&
        typeof moduleExports.name === 'string'
    ) {
        return moduleExports.name
    }

    return ''
}

export { GetTypeHandler, getModuleExportName, getObjectExportName }
